using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class TrainingPlanningTests
{
 class User(int id=1,bool hr=true):ICurrentUser{public string Email=>$"planner{id}@example.local";public int? EmployeeId=>id;public int UserId=>id;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>hr;public bool Can(string p)=>hr;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static TalentService S(AppDbContext d,int id=1,bool hr=true){var u=new User(id,hr);var c=new AppClock(TimeProvider.System);return new(d,u,new AccessScope(d,u),c,new AuditService(d,u,c),new NotificationService(d,u,c));}
 [Fact]public async Task NewPlanRequiresIndependentApprovalBeforeEnrolment(){await using var d=await Db();await S(d).AddCourseAsync("Demo planning",null,4,new(2027,1,4),"Need practice with safe data",2500,"EGP");var c=await d.Set<TrainingCourse>().SingleAsync(x=>x.Title=="Demo planning");Assert.Equal("Pending",c.ApprovalStatus);Assert.Equal(2500,c.PlannedBudget);await Assert.ThrowsAsync<DomainException>(()=>S(d,6,false).EnrollAsync(c.Id,6));await Assert.ThrowsAsync<DomainException>(()=>S(d).DecideCourseAsync(c.Id,true,"Self"));await S(d,2).DecideCourseAsync(c.Id,true,"Observed need and reviewed plan");await S(d,6,false).EnrollAsync(c.Id,6);Assert.True(await d.Set<TrainingEnrollment>().AnyAsync(x=>x.CourseId==c.Id&&x.EmployeeId==6));await Assert.ThrowsAsync<DomainException>(()=>S(d,2).DecideCourseAsync(c.Id,false,"Rewrite"));}
 [Fact]public async Task RejectedPlanNeverAcceptsEnrolmentAndReasonRequired(){await using var d=await Db();await S(d).AddCourseAsync("Rejected demo",null,2,new(2027,1,4),"Need",null,null);var c=await d.Set<TrainingCourse>().SingleAsync(x=>x.Title=="Rejected demo");await Assert.ThrowsAsync<DomainException>(()=>S(d,2).DecideCourseAsync(c.Id,false,""));await S(d,2).DecideCourseAsync(c.Id,false,"Not appropriate for stated need");await Assert.ThrowsAsync<DomainException>(()=>S(d,6,false).EnrollAsync(c.Id,6));}
 [Fact]public async Task PlanningInputsAndPermissionAreValidated(){await using var d=await Db();await Assert.ThrowsAsync<DomainException>(()=>S(d,6,false).AddCourseAsync("Denied",null,2,new(2027,1,4),"Need"));await Assert.ThrowsAsync<DomainException>(()=>S(d).AddCourseAsync("No need",null,2,new(2027,1,4)));await Assert.ThrowsAsync<DomainException>(()=>S(d).AddCourseAsync("Bad currency",null,2,new(2027,1,4),"Need",2500,""));await Assert.ThrowsAsync<DomainException>(()=>S(d).AddCourseAsync("Negative",null,2,new(2027,1,4),"Need",-1,"EGP"));}
 [Fact]public async Task ExistingCoursesRemainLegacyWithoutFabricatedApproval(){await using var d=await Db();Assert.All(await d.Set<TrainingCourse>().ToListAsync(),x=>{Assert.Equal("Legacy",x.ApprovalStatus);Assert.Null(x.DecidedAt);Assert.Null(x.CreatedByUserId);});}
 [Fact]public async Task UpgradePreservesLegacyCoursesAndOpeningsWithoutInventingApproval(){await using var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();var migrator=d.GetService<Microsoft.EntityFrameworkCore.Migrations.IMigrator>();await migrator.MigrateAsync("20261124190800_RecruitmentRequisition");await d.Database.ExecuteSqlRawAsync("INSERT INTO TrainingCourse (Title,TitleAr,Hours,Date,Revision,ApprovalStatus,Currency,DecisionReason,Need) VALUES ('Pre-upgrade','','4','2026-12-01','r','','','','')");await d.Database.ExecuteSqlRawAsync("INSERT INTO JobOpening (Title,TitleAr,Positions,IsOpen,CreatedAt,Revision,ApprovalReason,ApprovalStatus,Justification) VALUES ('Pre-upgrade','',1,1,'2026-11-24','r','','','')");await d.Database.MigrateAsync();var course=await d.Set<TrainingCourse>().SingleAsync();var job=await d.Set<JobOpening>().SingleAsync();Assert.Equal("Legacy",course.ApprovalStatus);Assert.Equal("Legacy",job.ApprovalStatus);Assert.Null(course.DecidedAt);Assert.Null(job.DecidedAt);Assert.True(job.IsOpen);}

 [Fact]public async Task DevelopmentCourseLinkCannotBypassPlanApproval(){await using var d=await Db();var u=new User();var clock=new AppClock(TimeProvider.System);var audit=new AuditService(d,u,clock);var perf=new PerfService(d,u,new AccessScope(d,u),clock,audit,new NotificationService(d,u,clock));var appraisal=await d.Set<PerfAppraisal>().FirstAsync(x=>x.EmployeeId==6);await S(d).AddCourseAsync("Development pending",null,4,new(2027,2,1),"Need safe data practice");var c=await d.Set<TrainingCourse>().SingleAsync(x=>x.Title=="Development pending");await Assert.ThrowsAsync<DomainException>(()=>perf.LinkCourseAsync(appraisal.Id,c.Id));Assert.False(await d.Set<TrainingEnrollment>().AnyAsync(x=>x.CourseId==c.Id));Assert.False(await d.Set<DevItem>().AnyAsync(x=>x.CourseId==c.Id));await S(d,2).DecideCourseAsync(c.Id,true,"Independent review");await perf.LinkCourseAsync(appraisal.Id,c.Id);Assert.True(await d.Set<TrainingEnrollment>().AnyAsync(x=>x.CourseId==c.Id&&x.EmployeeId==6));}
 [Fact]public async Task RecruitmentReadMethodsRequireTalentPermission(){await using var d=await Db();await Assert.ThrowsAsync<DomainException>(()=>S(d,6,false).JobsAsync());await Assert.ThrowsAsync<DomainException>(()=>S(d,6,false).CandidatesAsync());Assert.NotNull(await S(d).JobsAsync());}
 [Fact]public async Task EnrolmentTouchesEmployeeRevisionAndRepeatIsRejected(){await using var d=await Db();var c=await d.Set<TrainingCourse>().FirstAsync();var e=(await d.Set<Employee>().FindAsync(6))!;var before=e.LeaveRequestStamp;await S(d,6,false).EnrollAsync(c.Id,6);Assert.NotEqual(before,e.LeaveRequestStamp);await Assert.ThrowsAsync<DomainException>(()=>S(d,6,false).EnrollAsync(c.Id,6));Assert.Single(await d.Set<TrainingEnrollment>().Where(x=>x.CourseId==c.Id&&x.EmployeeId==6).ToListAsync());Assert.True(await d.Set<AuditLog>().AnyAsync(x=>x.Action=="Enroll"));}
 [Fact]public async Task TrainingParticipantProjectionContainsOnlyRosterFields(){await using var d=await Db();var c=await d.Set<TrainingCourse>().FirstAsync();await S(d,6,false).EnrollAsync(c.Id,6);var rows=await S(d,6,false).EnrollmentsAsync();Assert.All(rows,x=>Assert.Equal(6,x.EmployeeId));Assert.Contains(rows,x=>x.CourseId==c.Id&&!string.IsNullOrWhiteSpace(x.FullName));Assert.Equal(new[]{"Completed","CourseId","EmployeeId","FullName","FullNameAr","Id"},typeof(TrainingParticipant).GetProperties().Select(x=>x.Name).OrderBy(x=>x).ToArray());}
 [Fact]public async Task CatalogueDoesNotReturnPrivatePlanningFieldsToEmployee(){await using var d=await Db();await S(d).AddCourseAsync("Private planning fixture",null,4,new(2027,1,4),"Private need",2500,"EGP");var source=await d.Set<TrainingCourse>().SingleAsync(x=>x.Title=="Private planning fixture");source.DecisionReason="Private decision";await d.SaveAsync();var view=(await S(d,6,false).CoursesAsync()).Single(x=>x.Id==source.Id);Assert.Equal("",view.Need);Assert.Null(view.PlannedBudget);Assert.Equal("",view.Currency);Assert.Equal("",view.DecisionReason);Assert.Null(view.CreatedByUserId);Assert.Equal(source.Title,view.Title);Assert.Equal("Private need",source.Need);Assert.Equal(2500,(await S(d).CoursesAsync()).Single(x=>x.Id==source.Id).PlannedBudget);}
}
